-- German curriculum (PLAN-multilingua.md, PR 8): 24 chapters A1-B2 x 4 lessons, same structure as the English one.
-- Titles and descriptions in Italian (the native language); grammar_focus and focus in English, for the prompts.
-- Written once and reviewed; the lessons themselves are generated (and shared) by the `lesson` function.

insert into public.chapters (language, level, sort_order, slug, title, description_it, grammar_focus) values
  ('de', 'A1', 1, 'a1-sein', 'Presentarsi', 'Il verbo sein, i saluti, i paesi, i numeri e la famiglia.', 'verb sein (present); subject pronouns; du vs Sie; greetings; kommen aus + countries; numbers; possessive articles mein/dein/sein/ihr in the nominative'),
  ('de', 'A1', 2, 'a1-artikel', 'Le cose intorno a me', 'Articoli, genere, plurale ed es gibt.', 'definite and indefinite articles der/die/das, ein/eine; negation kein/keine; plural forms; es gibt + accusative; prepositions of place in/auf/unter/neben'),
  ('de', 'A1', 3, 'a1-praesens', 'La mia giornata', 'Il presente dei verbi, i verbi separabili e l''ora.', 'present tense of regular verbs; vowel-changing verbs (e>i, e>ie, a>ä); separable verbs; verb in second position; telling the time; am/um/im'),
  ('de', 'A1', 4, 'a1-fragen', 'Domande e negazioni', 'Fare domande, negare e dire cosa piace.', 'yes/no questions (verb first) and W-questions; doch; nicht vs kein; gern / lieber / am liebsten; mögen'),
  ('de', 'A1', 5, 'a1-modalverben', 'Potere, volere, dovere', 'I verbi modali, l''imperativo e le indicazioni.', 'modal verbs können, wollen, müssen, dürfen, möchten and the infinitive at the end; imperative (du, ihr, Sie); asking for and giving directions'),
  ('de', 'A1', 6, 'a1-akkusativ', 'L''accusativo', 'L''accusativo con articoli e pronomi, i vestiti e il tempo.', 'accusative case of articles (den/einen/keinen) and possessives; accusative personal pronouns; verbs with the accusative (haben, brauchen, kaufen); clothes; weather'),
  ('de', 'A2', 1, 'a2-perfekt-haben', 'Ieri', 'Il Perfekt con haben e le espressioni di tempo.', 'Perfekt with haben; past participle of regular (ge-...-t) and irregular verbs (ge-...-en); participle at the end of the sentence; past time expressions (gestern, letzte Woche, vor + dative)'),
  ('de', 'A2', 2, 'a2-perfekt-sein', 'Raccontare il passato', 'Il Perfekt con sein, i verbi separabili e il Präteritum di sein e haben.', 'Perfekt with sein (movement and change of state); Perfekt of separable and inseparable verbs; Präteritum of sein and haben; sequencing words'),
  ('de', 'A2', 3, 'a2-dativ', 'Il dativo', 'Il dativo con articoli, pronomi, preposizioni e verbi.', 'dative case of articles and possessives; prepositions with the dative (mit, bei, nach, von, zu, aus, seit); dative pronouns; verbs with the dative (helfen, gefallen, gehören); two-way prepositions (wo? + dative / wohin? + accusative)'),
  ('de', 'A2', 4, 'a2-komparativ', 'Fare confronti', 'Comparativo, superlativo e le forme irregolari.', 'comparative (-er + als); so ... wie; superlative (am -sten, der/die/das -ste); umlaut in short adjectives; irregular gut/besser, viel/mehr, gern/lieber'),
  ('de', 'A2', 5, 'a2-nebensaetze', 'Perché e quando', 'Le frasi secondarie con weil, dass e wenn.', 'subordinate clauses with weil, dass, wenn and the verb at the end; denn vs weil; subordinate clause before the main clause (verb-verb)'),
  ('de', 'A2', 6, 'a2-adjektive', 'Descrivere', 'La declinazione degli aggettivi.', 'adjective endings after the definite article and after ein/kein/possessives in the nominative, accusative and dative; describing people, flats and clothes'),
  ('de', 'B1', 1, 'b1-praeteritum', 'Raccontare una storia', 'Il Präteritum, als e wenn e il Plusquamperfekt.', 'Präteritum of regular and irregular verbs in written narration; als vs wenn; Plusquamperfekt; nachdem and bevor'),
  ('de', 'B1', 2, 'b1-futur', 'Il futuro e i progetti', 'Il futuro con werden e il presente per il futuro.', 'Futur I with werden; present tense with time expressions for the future; werden for suppositions; vorhaben, planen, Lust haben + zu'),
  ('de', 'B1', 3, 'b1-konjunktiv', 'Se fossi...', 'Il Konjunktiv II per desideri, cortesia, consigli e ipotesi.', 'Konjunktiv II with würde + infinitive and wäre, hätte, könnte, müsste, sollte; wishes; polite requests; advice; unreal conditions with wenn'),
  ('de', 'B1', 4, 'b1-passiv', 'La forma passiva', 'Il passivo al presente, al passato e con i verbi modali.', 'Vorgangspassiv with werden in the present and Präteritum; passive with modal verbs (muss gemacht werden); von + dative for the agent'),
  ('de', 'B1', 5, 'b1-relativsaetze', 'Frasi relative', 'I pronomi relativi al nominativo, accusativo e dativo e con preposizione.', 'relative clauses with der/die/das in the nominative, accusative and dative; verb at the end; preposition + relative pronoun; was and wo as relatives'),
  ('de', 'B1', 6, 'b1-infinitiv', 'L''infinito con zu', 'Zu + infinito, um ... zu, damit e i verbi con preposizione.', 'zu + infinitive after verbs and expressions; um ... zu vs damit; ohne ... zu; verbs with fixed prepositions (warten auf, sich freuen auf/über, denken an); da- and wo- compounds'),
  ('de', 'B2', 1, 'b2-konjunktiv-vergangenheit', 'Rimpianti e ipotesi', 'Il Konjunktiv II al passato e als ob.', 'Konjunktiv II in the past (hätte / wäre + Partizip II); with modal verbs (hätte machen sollen); unreal wishes (wenn ... doch); als ob / als wenn'),
  ('de', 'B2', 2, 'b2-genitiv', 'Il genitivo', 'Il genitivo, le preposizioni con il genitivo e dessen / deren.', 'genitive case of articles and nouns (-s/-es); prepositions with the genitive (wegen, trotz, während, statt, innerhalb, außerhalb); relative pronouns dessen / deren'),
  ('de', 'B2', 3, 'b2-konnektoren', 'Collegare le idee', 'Connettivi per argomentare e scrivere testi chiari.', 'concession and contrast (obwohl, trotzdem, dennoch, während); consequence (deshalb, deswegen, sodass); two-part connectors (zwar ... aber, sowohl ... als auch, weder ... noch, entweder ... oder); je ... desto; word order after connectors'),
  ('de', 'B2', 4, 'b2-indirekte-rede', 'Il discorso indiretto', 'Il Konjunktiv I per riferire e le domande indirette.', 'reported speech with Konjunktiv I (er sagt, er sei / habe); Konjunktiv II as a replacement; indirect questions with ob and W-words; reporting the news'),
  ('de', 'B2', 5, 'b2-passiv-alternativen', 'Passivo avanzato', 'Il passivo di stato e le alternative al passivo.', 'Zustandspassiv (sein + Partizip II); passive in the Perfekt (ist ... worden); alternatives: man, sich lassen, sein + zu, adjectives in -bar'),
  ('de', 'B2', 6, 'b2-nominalstil', 'Lo stile formale', 'Nominalizzazione, participi come aggettivi e verbi funzionali.', 'nominalisation of verbs (beim Lesen, die Entscheidung); Partizip I and II as attributes (der lachende Mann, das gekaufte Buch); extended attributes; Funktionsverbgefüge (eine Entscheidung treffen, in Frage kommen)');

