  ('b2-nominalstil', 4, 'b2-nominalstil-funktionsverben', 'Prendere una decisione', 'Funktionsverbgefüge: eine Entscheidung treffen, zur Verfügung stehen, in Frage kommen')
) as l (chapter_slug, sort_order, slug, title, focus)
join public.chapters c on c.language = 'de' and c.slug = l.chapter_slug;
